'use strict';
let playState={coins:40,plots:[0,0,0,0,0,0],harvests:0,nickname:'时光过客',level:1,xp:0,hp:100,enemy:null,log:['江湖路远，先练好第一招。'],chapter:0};try{const p=JSON.parse(localStorage.getItem('archaeo-games')||'{}');for(const k of ['coins','harvests','level','xp','hp','chapter'])if(Number.isFinite(p[k])&&p[k]>=0)playState[k]=Math.min(p[k],100000);if(Array.isArray(p.plots)&&p.plots.length===6)playState.plots=p.plots.map(x=>[0,1,2,3].includes(x)?x:0);if(typeof p.nickname==='string')playState.nickname=p.nickname.slice(0,16);if(p.enemy&&Number.isFinite(p.enemy.hp)&&Number.isFinite(p.enemy.max)&&Number.isFinite(p.enemy.attack)&&typeof p.enemy.name==='string')playState.enemy=p.enemy;if(Array.isArray(p.log))playState.log=p.log.filter(x=>typeof x==='string').slice(0,5)}catch{}
function savePlay(){try{localStorage.setItem('archaeo-games',JSON.stringify(playState))}catch{toast('本设备暂时无法保存游戏进度')}}
const sceneNames={homeworld:'QQ家园 · 怀旧复刻',garden:'开心菜园',wutang:'精武堂 · 怀旧复刻',novels:'掌上书房',friends:'朋友网 · 同学录'};
function openScene(id){navigate({type:'scene',scene:id,name:sceneNames[id],url:'archaeo://'+id})}
function gameNote(){return '<p class="scene-note">原创怀旧互动 · 非腾讯或其他原站服务。进度只保存在本设备，游戏进程不代表真实历史。</p>'}
function sceneHeader(id,subtitle){return `<div class="scene-banner"><span>${id==='wutang'?'武':id==='garden'?'田':id==='novels'?'书':'家'}</span><div><h1>${sceneNames[id]}</h1><p>${subtitle}</p></div></div><nav class="scene-nav"><button data-scene="homeworld">家园</button><button data-scene="garden">种菜</button><button data-scene="wutang">精武堂</button><button data-scene="novels">小说</button><button data-scene="friends">朋友</button><button data-action="home">首页</button></nav>`}
function renderScene(p){const id=p.scene;let body='';if(id==='friends')body=friendsScene();if(id==='homeworld')body=`<section class="scene-box"><h2>欢迎回家，${escapeHTML(playState.nickname)}</h2><div class="profile-row"><div class="pixel-avatar">☺</div><div><b>${escapeHTML(playState.nickname)}</b><p>身份：时光旅人　｜　精武堂 Lv.${playState.level}<br>菜园收获：${playState.harvests} 次</p></div></div><form id="nickname-form"><label for="nickname-input">我的昵称</label><div class="inline-form"><input id="nickname-input" maxlength="16" value="${escapeHTML(playState.nickname)}" required><button class="primary">修改</button></div></form></section><section class="scene-box"><h2>家园小路</h2><div class="family-links"><button data-scene="garden">❀ 去菜园浇浇水 <span>播种 · 成长 · 收获</span></button><button data-scene="wutang">⚔ 精武堂练功闯关 <span>练功 · 对战 · 升级</span></button><button data-scene="novels">▤ 到书房读小说 <span>章节 · 书签 · 续读</span></button><button data-scene="friends">☻ 朋友网同学录 <span>在本机记住老朋友</span></button><a href="https://web.archive.org/web/${year()}*/http://3g.qq.com/" data-site="3g.qq.com" data-name="QQ移动站历史存档">↗ 寻找 QQ 移动站旧页面</a></div></section>`;
if(id==='garden')body=`<div class="garden-stats"><span>铜钱 <b>${playState.coins}</b></span><span>累计收获 <b>${playState.harvests}</b></span><span>萝卜种子 <b>5文</b></span></div><div class="garden-landscape"><div class="garden-sun">☀</div><span class="garden-fence">╬ ╬ ╬ ╬ ╬ ╬ ╬ ╬ ╬</span><div class="garden-plots">${playState.plots.map((stage,i)=>`<button class="plot stage-${stage}" data-plot="${i}" aria-label="第${i+1}块地：${['播种','浇水','再浇水','收获'][stage]}"><span class="crop-art">${['·','🌱','🌿','🥕'][stage]}</span><span class="plot-label">${['播种 −5','浇水 1/2','浇水 2/2','收获 +15'][stage]}</span></button>`).join('')}</div></div><section class="scene-box"><h2>种菜小贴士</h2><p>点空地播种，浇水两次就能收获。没有真实等待计时，随时回来玩。</p><button class="scene-button" data-game="waterall">♧ 照料全部菜地</button></section>`;
if(id==='wutang'){const enemy=playState.enemy;const max=100+(playState.level-1)*10;body=`<div class="wutang-stage"><div class="mountain m1"></div><div class="mountain m2"></div><div class="wutang-moon"></div><div class="fighters"><div><span class="fighter">侠</span><b>${escapeHTML(playState.nickname)}</b><small>Lv.${playState.level} · ${playState.hp}/${max}</small><progress max="${max}" value="${playState.hp}"></progress></div><span class="versus">${enemy?'VS':'修行'}</span><div><span class="fighter enemy">${enemy?'敌':'山'}</span><b>${enemy?escapeHTML(enemy.name):'山门石阶'}</b><small>${enemy?`${enemy.hp}/${enemy.max}`:'静候来者'}</small>${enemy?`<progress max="${enemy.max}" value="${enemy.hp}"></progress>`:''}</div></div></div><div class="wutang-xp">修为 ${playState.xp} / ${playState.level*30} <progress max="${playState.level*30}" value="${playState.xp}"></progress></div><div class="combat-actions">${enemy?'<button data-game="attack">⚔ 出招</button><button data-game="guard">盾 守势反击</button><button data-game="flee">撤退</button>':'<button data-game="train">练功 +10修为</button><button data-game="challenge">挑战山门</button><button data-game="rest">打坐恢复</button>'}</div><section class="scene-box"><h2>江湖札记</h2><ol class="combat-log">${playState.log.map(l=>`<li>${escapeHTML(l)}</li>`).join('')}</ol><p class="scene-note">出招伤害高；守势反击伤害较低、承伤更少。挑战胜利得修为，落败可打坐恢复。</p></section>`}
if(id==='novels'){const chapter=Math.max(0,Math.min(2,playState.chapter));body=`<section class="scene-box"><h2>继续阅读</h2><div class="book-entry"><span class="book-cover">江<br>湖<br>来<br>信</span><div><b>江湖来信</b><p>原创演示短篇 · 共三回<br>上次读到：第 ${chapter+1} 回</p><button class="scene-button" data-read="${chapter}">继续阅读 →</button></div></div></section><section class="scene-box"><h2>小说站历史入口</h2><p>寻找那个年代的书站页面。能否打开、章节是否完整，以实际存档为准。</p><div class="wap-site-links">${[['起点中文网','www.qidian.com'],['红袖添香','www.hongxiu.com'],['榕树下','www.rongshuxia.com']].map(x=>siteLink(x[0],x[1])).join('')}</div></section>`}
return `<article class="scene-page scene-${id}">${sceneHeader(id,id==='wutang'?'一招一式，慢慢成为江湖中人。':id==='garden'?'有一块小田，就有一点惦记。':id==='novels'?'小小屏幕，也装得下一个江湖。':'家园复刻 · 留一盏灯，等你回来。')}${body}${gameNote()}</article>`}
const story=[{title:'第一回 · 旧信',text:['镇上的邮局拆去招牌那天，阿砚收到了一封没有署名的信。信封泛黄，邮戳却是明天的日期。','信里只有一行字：今夜三更，带着你父亲留下的木剑，到渡口来。','阿砚翻遍柜底，找到那柄断了一寸的木剑。剑柄下刻着一个他从未见过的字。窗外的雨忽然停了，远处传来渡船的铃声。']},{title:'第二回 · 渡口',text:['渡口没有船，只有一个披蓑衣的老人。他看了看木剑，说：“你迟到了十年。”','“我今年才十六。”阿砚回答。','老人没有争辩。他把一枚铜钱放在石阶上，铜钱一面是山，一面是水。水面随即亮起一条路，通向雾里看不见的山门。','“你父亲没有失踪，”老人说，“他只是还没走完那条路。”']},{title:'第三回 · 山门',text:['山门没有锁。阿砚推开门，看见院子里种着六畦青菜。一个比他年长不了多少的人，正蹲在那里浇水。','那人抬起头，眉眼像极了旧照片里的父亲。','阿砚握紧木剑，想问许多问题，最后却只说出一句：“我回来了。”','“先吃饭，”那人笑道，“江湖的事，吃过饭慢慢讲。”院外的钟响了一声，原来漫长的归途，也可以从一个寻常的晚上开始。']}];
function readChapter(n){n=Math.max(0,Math.min(2,n));playState.chapter=n;savePlay();const c=story[n];dialog('掌上阅读 · 江湖来信',`<article class="novel-reader"><small>原创演示短篇 · 非历史连载</small><h2>${c.title}</h2>${c.text.map(t=>`<p>${t}</p>`).join('')}<div class="reader-nav"><button class="secondary" data-read="${n-1}" ${n===0?'disabled':''}>上一回</button><span>${n+1} / 3</span><button class="secondary" data-read="${n+1}" ${n===2?'disabled':''}>下一回</button></div><p class="scene-note">阅读进度自动保存在本设备。</p></article>`)}
function levelUp(){while(playState.xp>=playState.level*30){playState.xp-=playState.level*30;playState.level++;playState.hp=100+(playState.level-1)*10;playState.log.unshift(`突破！你已升到 Lv.${playState.level}。`)}}
function refreshScene(){savePlay();$('#content').innerHTML=renderScene(current)}
function game(a){const s=playState;const max=100+(s.level-1)*10;if(a==='waterall'){s.plots=s.plots.map(p=>p===1||p===2?p+1:p);toast('已照料所有生长中的菜地')}if(a==='train'&&!s.enemy){s.xp+=10;s.log.unshift('静心练功，修为 +10。');levelUp()}if(a==='rest'&&!s.enemy){s.hp=max;s.log.unshift('打坐调息，气血已恢复。')}if(a==='challenge'&&!s.enemy){if(s.hp<=0){toast('先打坐恢复，再来挑战');return}s.enemy={name:['山门弟子','青衣剑客','竹林守卫'][(s.level-1)%3],hp:45+s.level*12,max:45+s.level*12,attack:10+s.level*2};s.log.unshift(`${s.enemy.name}向你抱拳，请赐教。`)}if(a==='flee'&&s.enemy){s.enemy=null;s.log.unshift('暂别擂台，回去继续修炼。')}if(['attack','guard'].includes(a)&&s.enemy&&s.hp>0){const hit= (a==='attack'?19:10)+s.level*4+Math.floor(Math.random()*7);s.enemy.hp=Math.max(0,s.enemy.hp-hit);s.log.unshift(`${a==='attack'?'你出招':'你守势反击'}，造成 ${hit} 点伤害。`);if(s.enemy.hp===0){s.xp+=25;s.coins+=10;s.enemy=null;s.log.unshift('闯关成功！修为 +25，铜钱 +10。');levelUp()}else{const hurt=Math.max(1,s.enemy.attack+(a==='attack'?3:-5));s.hp=Math.max(0,s.hp-hurt);s.log.unshift(`对手还击，你损失 ${hurt} 点气血。`);if(s.hp===0){s.enemy=null;s.log.unshift('本次惜败。回到山门，打坐后再来。')}}}s.log=s.log.slice(0,5);refreshScene()}
document.addEventListener('click',e=>{const el=e.target.closest('a,button');if(!el)return;if(el.dataset.scene){e.preventDefault();$('#modal').close();openScene(el.dataset.scene)}if(el.dataset.game)game(el.dataset.game);if(el.dataset.plot!==undefined){const i=Number(el.dataset.plot);let p=playState.plots[i];if(p===0){if(playState.coins<5){toast('铜钱不足，可去精武堂闯关赚取');return}playState.coins-=5;playState.plots[i]=1;toast('萝卜种下了，记得来浇水')}else if(p===3){playState.coins+=15;playState.harvests++;playState.plots[i]=0;toast('收获萝卜，铜钱 +15')}else{playState.plots[i]++;toast(playState.plots[i]===3?'萝卜成熟了，可以收获！':'浇水成功，再照料一次就长大了')}refreshScene()}if(el.dataset.read!==undefined)readChapter(Number(el.dataset.read));if(el.dataset.scrollNews!==undefined)document.querySelector('.annual-news[data-context="mobile"]')?.scrollIntoView({behavior:'smooth',block:'center'})});
document.addEventListener('submit',e=>{if(e.target.id==='nickname-form'){e.preventDefault();const n=$('#nickname-input').value.trim();if(!n)return toast('请写一个昵称');playState.nickname=n.slice(0,16);refreshScene();toast('昵称已保存在本设备')}});
let localFriends=[];try{const f=JSON.parse(localStorage.getItem('archaeo-friends')||'[]');if(Array.isArray(f))localFriends=f.filter(x=>x&&typeof x.name==='string'&&typeof x.note==='string').slice(0,50)}catch{}
function friendsScene(){return `<section class="scene-box"><h2>我的本机同学录</h2><p>留一个名字，记住一段旧时光。这里只保存在本机，不查找真实账号，也不发送消息。</p>${localFriends.length?localFriends.map((f,i)=>`<div class="friend-card"><div class="pixel-avatar">☺</div><div><b>${escapeHTML(f.name)}</b><small>${escapeHTML(f.note)}</small></div><button data-friend-remove="${i}" aria-label="移除${escapeHTML(f.name)}">×</button></div>`).join(''):'<p class="scene-note">同学录还是空的。你最想记住谁？</p>'}</section><section class="scene-box"><h2>记下一个老朋友</h2><form id="friend-form"><label for="friend-name">朋友的昵称</label><div class="inline-form"><input id="friend-name" maxlength="20" placeholder="例如：隔壁班的小林" required></div><label for="friend-note">一句回忆</label><div class="inline-form"><input id="friend-note" maxlength="60" placeholder="一起在网吧打过游戏"><button class="primary">记下</button></div></form></section><section class="scene-box"><h2>真实历史页面</h2>${siteLink('寻找朋友网 pengyou.com 的历史页面','www.pengyou.com')}<p class="scene-note">不同年份可能没有存档；上面的同学录是本应用的原创复刻。</p></section>`}
function saveFriends(){try{localStorage.setItem('archaeo-friends',JSON.stringify(localFriends))}catch{toast('同学录保存失败，请检查浏览器存储设置')}}
document.addEventListener('submit',e=>{if(e.target.id==='friend-form'){e.preventDefault();const name=$('#friend-name').value.trim(),note=$('#friend-note').value.trim();if(!name)return;if(localFriends.length>=50)return toast('本机同学录最多保存50位朋友');localFriends.push({name:name.slice(0,20),note:note.slice(0,60)});saveFriends();refreshScene();toast('已记在本机同学录')}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-friend-remove]');if(b){localFriends.splice(Number(b.dataset.friendRemove),1);saveFriends();refreshScene()}});
